// This is file of your component
// You can use any dependencies from npm; we import them automatically in package.json

"use client";

import * as React from "react";
import { motion, useMotionTemplate, useMotionValue, useReducedMotion } from "framer-motion";
import { ArrowRight, Star } from "lucide-react";
import { cn } from "@/lib/utils";

export interface AvatarItem {
  name: string;
  initials: string;
  imageUrl?: string;
}

export interface ComponentProps {
  eyebrow?: string;
  headline: string;
  subheadline: string;
  primaryCtaLabel: string;
  secondaryCtaLabel?: string;
  onPrimaryClick?: () => void;
  onSecondaryClick?: () => void;
  avatars?: AvatarItem[];
  trustedByText?: string;
  rating?: number;
  className?: string;
}

export function Component({
  eyebrow,
  headline,
  subheadline,
  primaryCtaLabel,
  secondaryCtaLabel,
  onPrimaryClick,
  onSecondaryClick,
  avatars = [],
  trustedByText,
  rating = 5,
  className,
}: ComponentProps) {
  const prefersReducedMotion = useReducedMotion();
  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);

  const handleMouseMove = (e: React.MouseEvent<HTMLElement>) => {
    if (prefersReducedMotion) return;
    const { left, top } = e.currentTarget.getBoundingClientRect();
    mouseX.set(e.clientX - left);
    mouseY.set(e.clientY - top);
  };

  const spotlightBackground = useMotionTemplate`radial-gradient(520px circle at ${mouseX}px ${mouseY}px, hsl(var(--primary) / 0.12), transparent 80%)`;

  const words = React.useMemo(() => headline.trim().split(/\s+/), [headline]);

  return (
    <section
      aria-label="Hero Section"
      onMouseMove={handleMouseMove}
      className={cn(
        "group relative flex min-h-[540px] w-full flex-col items-center justify-center overflow-hidden bg-background px-4 py-24 text-center text-foreground sm:px-6 lg:px-8",
        className
      )}
    >
      {/* Static Ambient Glow */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute top-0 left-1/2 -z-10 h-[320px] w-[640px] -translate-x-1/2 -translate-y-1/2 rounded-full bg-primary/10 blur-[120px]"
      />

      {/* Mouse-Reactive Spotlight */}
      {!prefersReducedMotion && (
        <motion.div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 -z-10 opacity-0 transition-opacity duration-500 group-hover:opacity-100"
          style={{ background: spotlightBackground }}
        />
      )}

      <div className="mx-auto flex max-w-4xl flex-col items-center">
        {/* Eyebrow Pill */}
        {eyebrow && (
          <motion.span
            initial={{ opacity: 0, y: prefersReducedMotion ? 0 : 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4 }}
            className="mb-6 inline-flex items-center rounded-full border border-border bg-secondary/70 px-3.5 py-1 text-xs font-medium tracking-wide text-secondary-foreground"
          >
            {eyebrow}
          </motion.span>
        )}

        {/* Kinetic Word-by-Word Blur Reveal Headline */}
        <h1 className="text-balance text-4xl font-bold tracking-tight sm:text-6xl md:text-7xl lg:leading-[1.08]">
          {words.map((word, index) => (
            <motion.span
              key={`${word}-${index}`}
              initial={
                prefersReducedMotion
                  ? { opacity: 0 }
                  : { opacity: 0, y: 16, filter: "blur(8px)" }
              }
              animate={
                prefersReducedMotion
                  ? { opacity: 1 }
                  : { opacity: 1, y: 0, filter: "blur(0px)" }
              }
              transition={{
                duration: prefersReducedMotion ? 0.15 : 0.45,
                delay: prefersReducedMotion ? 0 : index * 0.06,
                ease: [0.22, 1, 0.36, 1],
              }}
              className="mr-[0.26em] inline-block last:mr-0"
            >
              {word}
            </motion.span>
          ))}
        </h1>

        {/* Subheadline */}
        <motion.p
          initial={{ opacity: 0, y: prefersReducedMotion ? 0 : 14 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{
            duration: 0.5,
            delay: prefersReducedMotion ? 0 : Math.min(words.length * 0.06 + 0.1, 0.6),
          }}
          className="mt-6 max-w-2xl text-pretty text-base text-muted-foreground sm:text-lg md:text-xl"
        >
          {subheadline}
        </motion.p>

        {/* Action Buttons */}
        <motion.div
          initial={{ opacity: 0, y: prefersReducedMotion ? 0 : 14 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{
            duration: 0.5,
            delay: prefersReducedMotion ? 0 : Math.min(words.length * 0.06 + 0.2, 0.7),
          }}
          className="mt-9 flex w-full flex-col items-center justify-center gap-3 sm:w-auto sm:flex-row sm:gap-4"
        >
          <button
            type="button"
            onClick={onPrimaryClick}
            className="group/btn inline-flex h-11 w-full items-center justify-center gap-2 rounded-full bg-primary px-7 text-sm font-medium text-primary-foreground shadow-sm transition-all hover:bg-primary/90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background sm:w-auto"
          >
            <span>{primaryCtaLabel}</span>
            <ArrowRight
              className="size-4 transition-transform duration-200 group-hover/btn:translate-x-0.5"
              aria-hidden="true"
            />
          </button>

          {secondaryCtaLabel && (
            <button
              type="button"
              onClick={onSecondaryClick}
              className="inline-flex h-11 w-full items-center justify-center rounded-full border border-border bg-background px-7 text-sm font-medium text-foreground transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background sm:w-auto"
            >
              {secondaryCtaLabel}
            </button>
          )}
        </motion.div>

        {/* Social Proof Footer */}
        {(avatars.length > 0 || trustedByText) && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{
              duration: 0.5,
              delay: prefersReducedMotion ? 0 : Math.min(words.length * 0.06 + 0.35, 0.85),
            }}
            className="mt-12 flex flex-col items-center gap-3 sm:flex-row sm:gap-4"
          >
            {avatars.length > 0 && (
              <div className="flex -space-x-2.5" aria-hidden="true">
                {avatars.map((avatar) => (
                  <div
                    key={avatar.name}
                    title={avatar.name}
                    className="flex size-8 items-center justify-center overflow-hidden rounded-full border-2 border-background bg-secondary text-[11px] font-semibold text-secondary-foreground shadow-sm"
                  >
                    {avatar.imageUrl ? (
                      <img
                        src={avatar.imageUrl}
                        alt={avatar.name}
                        className="size-full object-cover"
                      />
                    ) : (
                      <span>{avatar.initials}</span>
                    )}
                  </div>
                ))}
              </div>
            )}

            <div className="flex flex-col items-center sm:items-start">
              <div className="flex items-center gap-0.5" aria-label={`${rating} out of 5 stars`}>
                {Array.from({ length: 5 }).map((_, i) => (
                  <Star
                    key={i}
                    className={cn(
                      "size-3.5",
                      i < rating
                        ? "fill-amber-400 text-amber-400"
                        : "fill-muted text-muted"
                    )}
                    aria-hidden="true"
                  />
                ))}
              </div>
              {trustedByText && (
                <p className="mt-0.5 text-xs text-muted-foreground">{trustedByText}</p>
              )}
            </div>
          </motion.div>
        )}
      </div>
    </section>
  );
}

export default Component;

